INSERT INTO public.scraped_reviews (id, facility_id, external_id, author_name, author_photo, rating, comment, relative_date, source, scraped_at) VALUES ('54416aa7-9385-43ae-af4d-e935878fcdeb', '624eb6b8-03ff-4cbc-af8c-afbbbc871881', 'Ci9DQUlRQUNvZENodHljRjlvT2xBMmRFMDRNbDlCZEd4VFUxTktVV2hTWlVaTFFYYxAB', 'Electrician UDIT KUMAR GAUD', 'https://lh3.googleusercontent.com/a-/ALV-UjXoR-kT99mUaso5x8fmSEP_ZRV7TFbcGW6EiT5yfIWsIXGRJIM=w36-h36-p-rp-mo-ba12-br100', 5, 'This marriage house is located near Khonhauli village on the Nichlaul-Maharajganj road. It is a beautiful and well-appointed marriage house. Guest rooms are also available for larger accommodation. 24-hour bus service is available from here to Gorakhpur, and rental cars, Maruti Suzuki, and Bolero vehicles are also available. This marriage house is quite large and has excellent parking. However, leftover food is thrown outside the marriage house on the roadside, which stinks and looks very unsightly. The management of this marriage house should consider this and dispose of the leftover food in a well-prepared compost pit elsewhere, to preserve the beauty of the marriage house and increase public attraction to it.', 'Edited 8 months ago', 'GOOGLE_MAPS', '2026-09-22 13:08:03.504199+05:30') ON CONFLICT DO NOTHING;
