INSERT INTO public.scraped_reviews (id, facility_id, external_id, author_name, author_photo, rating, comment, relative_date, source, scraped_at) VALUES ('25fc9730-1f5d-408e-9726-cdc89a427cbb', 'a8f142ad-8e91-4cbb-898b-980774fa99a8', 'ChdDSUhNMG9nS0VJQ0FnSUQxdS1lUHhBRRAB', 'SBSY ROCK', 'https://lh3.googleusercontent.com/a-/ALV-UjV-QxKCMzd-se0ekkrlca2r9OYouqHj0y0otML0Afe9Bv1drxz4=w36-h36-p-rp-mo-ba12-br100', 5, 'My favourite place is the beach. At the beach, I feel joyful and have fun at the same time. I can enjoy the water and the sunset and have lots of fun. Mom says the sun’s rays are good for getting vitamin D while we have some fun on the beach. We can enjoy many fun activities on the beach, like playing beach ball or making a sand castle. My father and brother also join me when I go to the beach with my mother. It is fun to have fun with the family at the beach. We make sand castles and collect a lot of sea shells. I wish to have a fishing boat and make a beach house when I grow up.', '2 years ago', 'GOOGLE_MAPS', '2026-09-22 13:28:34.445981+05:30') ON CONFLICT DO NOTHING;
INSERT INTO public.scraped_reviews (id, facility_id, external_id, author_name, author_photo, rating, comment, relative_date, source, scraped_at) VALUES ('dbba8f2a-0fe9-4507-8757-81409a2e874b', 'a8f142ad-8e91-4cbb-898b-980774fa99a8', 'Ci9DQUlRQUNvZENodHljRjlvT204dGJ6WTJXVWhRUTJsd1FsQlFRV3hsWVhVd2MxRRAB', 'physicskingdeepak', 'https://lh3.googleusercontent.com/a-/ALV-UjVFAyEAp-sTRGaQEotS1TrEmhRjjxTtwJi1bHsx-rz0SEe50wc=w36-h36-p-rp-mo-br100', 5, 'We hosted our sister reception at Shanrda marriage hall for 500 guests, and the experience was truly memorable. The hall''s opulent ambiance and decorations were stunning, easily accommodating our large group. The in-house catering was exceptional, with every guest praising the delicious menu variety and prompt service. While slightly pricey, the dedicated staff and manager ensured a completely seamless and stress-free event. I highly recommend
