INSERT INTO public.scraped_reviews (id, facility_id, external_id, author_name, author_photo, rating, comment, relative_date, source, scraped_at) VALUES ('b406f32e-9e26-42bc-8497-caaa67690432', '2b7e6461-0794-4837-92e4-1453522e8db7', 'Ci9DQUlRQUNvZENodHljRjlvT2xablVWWkRWRlp1WW1oNFgyZG9ZekZCZEVWQ1NXYxAB', 'kirpal kumar', 'https://lh3.googleusercontent.com/a-/ALV-UjXyw91FuI-T0-OjuxxFVfm7PrDmm6pzjlv0W_R8nMI9ecqKOD0C=w36-h36-p-rp-mo-ba12-br100', NULL, 'Had a fantastic stay here! We booked a room for the entire day and were thoroughly impressed by the excellent service and prompt responses. The staff is polite, attentive, and constantly checked in to ensure we had everything we needed. The rooms are great, with both AC and Non-AC options, and the attached washrooms were perfectly clean.The absolute best part of our experience was the owner. When our bus got delayed, he generously let us stay for a couple of extra hours without charging us a single penny. His genuine kindness and hospitality made a huge difference. Highly recommended!
